function blueUpdateChapter(){const i=blueChapters.indexOf(activeRoute);if($('bluePrev')){$('bluePrev').disabled=i<=0;$('blueNext').disabled=i>=blueChapters.length-1}document.body.dataset.screen=activeRoute;document.querySelectorAll('#appNav [data-route]').forEach(b=>{if(b.dataset.route===activeRoute)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')})}

function executiveRoundData(){return D.auctionContext.rounds.map(r=>{const a=D.areaScenario.areas.filter(x=>x.round===r.round),u=a.filter(x=>x.unpaid),paid=a.length-u.length,c=a.filter(x=>x.cfem_cents>0);return {...r,year:a[0]?.homologation?.slice(0,4)||({6:'2022',7:'2022–2023'}[r.round]||''),unpaid:u.length,unpaidValue:u.reduce((s,x)=>s+x.cents,0),paid,saldo:r.cents-u.reduce((s,x)=>s+x.cents,0),cfemAreas:c.length,cfem:c.reduce((s,x)=>s+x.cfem_cents,0)}})}
function executiveChart(rows,key,label,moneyMetric=true){let acc=0;const rr=rows.map(r=>({...r,v:[6,7].includes(r.round)?0:r[key],acc:acc+=([6,7].includes(r.round)?0:r[key])})),max=Math.max(1,...rr.map(r=>r.acc)),w=960,h=310,base=238,scale=180/max;const format=v=>moneyMetric?'R$ '+(v/1e8).toLocaleString('pt-BR',{maximumFractionDigits:1})+' mi':num(v);return `<div class="executiveChart"><h3>${label}</h3><p class="note">Colunas: cada rodada · linha: acumulado · mesma escala, a partir de zero</p><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${label}: por rodada e acumulado"><line x1="30" y1="${base}" x2="940" y2="${base}" stroke="#9aaec1"/><polyline fill="none" stroke="#174a7e" stroke-width="3" points="${rr.map((r,i)=>(85+i*112)+','+(base-r.acc*scale)).join(' ')}"/>${rr.map((r,i)=>{const x=85+i*112;return `<g><title>${r.round}ª rodada: ${[6,7].includes(r.round)?'não se aplica':format(r.v)}; acumulado ${format(r.acc)}</title><rect x="${x-23}" y="${base-r.v*scale}" width="46" height="${r.v*scale}" rx="4" fill="#8ab8d8"/><circle cx="${x}" cy="${base-r.acc*scale}" r="4" fill="#174a7e"/><text x="${x}" y="${base-r.acc*scale-13}" text-anchor="middle" font-size="12" fill="#174a7e">${format(r.acc)}</text><text x="${x}" y="265" text-anchor="middle" font-size="13">${r.round}ª · ${r.year}</text><text x="${x}" y="290" text-anchor="middle" font-size="12">${r.round===6?'Social':r.round===7?'Cancelada':format(r.v)}</text></g>`}).join('')}</svg><p class="note">Rodadas 6 e 7 não acrescentam valores comerciais. A tabela contém os valores exatos.</p></div>`}
function executiveOverview(){const s=D.areaScenario.summary,stock=D.stockSummary,S=D.socialRound6,rows=executiveRoundData();let box=$('executiveSummary');if(!box){box=document.createElement('section');box.id='executiveSummary';box.className='blueSection';$('editorialOpening').after(box);routeNodes.set(box,'results')}box.innerHTML=`<span class="blueKicker">Panorama geral · até junho de 2026 para CFEM</span><h2>Quanto foi ofertado — e o que aconteceu depois?</h2><div class="executiveMetrics">${[[money(s.bid_cents/100),'Lances vencedores',num(s.awarded)+' arremates de áreas'],[money(s.unpaid_cents/100),'Não pagamento identificado',num(s.unpaid)+' áreas · '+pct(s.unpaid,s.awarded)+' dos arremates'],[money((s.bid_cents-s.unpaid_cents)/100),'Receita estimada dos lances',num(s.estimated_paid)+' áreas com pagamento estimado · '+pct(s.estimated_paid,s.awarded)],[money(s.cfem_cents/100),'CFEM encontrada depois',num(s.cfem_areas)+' áreas · '+pct(s.cfem_areas,s.estimated_paid)+' do grupo com pagamento estimado']].map(([n,t,c])=>`<article><span>${t}</span><strong>${n}</strong><p>${c}</p></article>`).join('')}</div><p class="blueNotice">Lances vencedores − valores com não pagamento identificado = <b>saldo estimado</b>. Não é receita líquida certificada: falta conciliação financeira. As ${num(s.estimated_paid)} áreas são o saldo dessa premissa; não significam que todas já obtiveram título ou iniciaram atividade. Os ${num(s.cfem_areas)} casos com CFEM pertencem ao acompanhamento posterior desse grupo.</p><div class="blueGrid two"><article><h3>Qual é o estoque para próximas rodadas?</h3><strong class="big">${num(stock.eligible_unique)} aptas</strong><p>Registros classificados como “Apta para Disponibilidade”, entre ${num(stock.unique_processes)} processos no estoque consultado. Retrato da extração de <b>${date(stock.extraction)}</b>, não saldo em tempo real nem oferta já aprovada.</p><p>${Object.entries(stock.statuses).filter(([k])=>k!=='Apta para Disponibilidade').map(([k,v])=>num(v)+' '+esc(k.toLowerCase())).join(' · ')}.</p></article><article><h3>A 6ª rodada tem outro caminho</h3><p><b>420 áreas</b> para seleção social de PLG → <b>${S.requested} requeridas</b> (${pct(S.requested,420)}) → <b>${S.with_links} com associados localizados</b> → <b>${S.cfem_origins} com CFEM</b> (${pct(S.cfem_origins,S.requested)} das requeridas).</p><strong class="big">${money(S.cfem_cents/100)}</strong><p>CFEM posterior preliminar, acompanhada após a associação até junho/2026. Receita de lance: <b>não se aplica</b>. Grupo separado do comercial; na PLG, a CFEM é recolhida pelo primeiro adquirente.</p><button onclick="navigate('social')">Ver as áreas da 6ª rodada →</button></article></div><button class="bluePrimary" onclick="navigate('rounds')">Comparar os resultados por rodada →</button><details class="blueSection"><summary>Perguntas frequentes · entenda o caminho das áreas</summary>${executiveFAQ()}</details>`;box.classList.toggle('routeHidden',activeRoute!=='results');
const review=$('roundPaymentReview');if(review){$('blueRoundPage').prepend(review);review.innerHTML=`<span class="blueKicker">Rodadas em sequência · panorama geral</span><h2>Da área ofertada ao recolhimento de CFEM</h2><p>Leia da esquerda para a direita: oferta, arremate, pagamento estimado e acompanhamento. Percentuais usam o denominador indicado em cada coluna.</p><div class="blueTableWrap"><table id="executiveRoundTable"><thead><tr><th>Rodada / ano</th><th>Áreas ofertadas*</th><th>Arrematadas / ofertadas</th><th>Valor dos lances vencedores</th><th>Não pagamento: áreas / valor</th><th>Áreas com pagamento estimado</th><th>Receita estimada dos lances</th><th>Áreas com CFEM posterior</th><th>CFEM até jun./2026</th></tr></thead><tbody>${rows.map(r=>r.round===6?`<tr><th>6ª · 2022 · social</th><td>420</td><td>${S.requested} requeridas · ${pct(S.requested,420)}</td><td colspan="4">Seleção social para PLG. Lance, arremate comercial e receita de lance não se aplicam. ${S.with_links} áreas com associados localizados.</td><td>${S.cfem_origins} · ${pct(S.cfem_origins,S.requested)} das requeridas</td><td>${money(S.cfem_cents/100)} · preliminar</td></tr>`:r.round===7?`<tr><th>7ª · 2022–2023</th><td>${num(r.included)} registradas</td><td colspan="7">Edital cancelado. Não é oferta concluída nem desempenho comercial zero.</td></tr>`:`<tr><th>${r.round}ª · ${r.year}</th><td>${num(r.included)}</td><td>${num(r.awarded)} · ${pct(r.awarded,r.included)}</td><td>${money(r.cents/100)}</td><td>${num(r.unpaid)} · ${pct(r.unpaid,r.awarded)} dos arremates<br>${money(r.unpaidValue/100)}</td><td>${num(r.paid)} · ${pct(r.paid,r.awarded)} dos arremates</td><td>${money(r.saldo/100)}</td><td>${num(r.cfemAreas)} · ${pct(r.cfemAreas,r.paid)} das áreas com pagamento estimado</td><td>${money(r.cfem/100)}</td></tr>`).join('')}</tbody></table></div><p class="note">* Áreas registradas por rodada na base, incluindo retiradas e suspensas; não é contagem certificada de oferta final. Ano das rodadas comerciais: homologação. Zero em não pagamento significa ausência de não pagamento identificado nesta análise, não comprovação bancária. CFEM e receita do lance são receitas distintas; não devem ser confundidas.</p>${executiveChart(rows,'saldo','Receita estimada dos lances por rodada e acumulada')}${executiveChart(rows,'cfem','CFEM posterior das áreas comerciais por rodada e acumulada')}<details><summary>FAQ · regras e próximos passos</summary>${executiveFAQ()}</details>`}
}
function executiveFAQ(){return `<div class="blueQuestions">${[
['Por que uma área entra em disponibilidade?','Por situações como renúncia, caducidade, indeferimento ou abandono, sujeitas ao tratamento administrativo cabível. Disponibilidade é um procedimento para selecionar interessados; não significa que a área esteja livre para requerimento imediato.'],
['Quem administra e como funciona a seleção?','A ANM conduz a disponibilidade. Nas rodadas comerciais acompanhadas, a oferta pública identifica interessados; com mais de um interessado, há disputa pelo maior valor financeiro. Com apenas um, pode haver direito de requerer sem leilão, conforme o edital. A plataforma e as condições devem ser conferidas no edital de cada rodada.'],
['O que o vencedor obtém?','O direito de prioridade para requerer a área, condicionado ao cumprimento das regras. Não compra a propriedade do minério nem recebe automaticamente um título ou licença ambiental.'],
['Qual é o lance mínimo e como se paga?','O valor mínimo, emolumentos, forma e prazo de pagamento constam do edital e dos atos aplicáveis à rodada. Não há um valor único presumido para todos os ciclos. O painel mostra os lances vencedores registrados; a confirmação financeira exige os registros de arrecadação correspondentes.'],
['O que acontece quando o vencedor não paga?','Pode perder o direito, com as consequências previstas no edital. O histórico pode registrar retorno à disponibilidade ou liberação da área. Esses desfechos são distintos e precisam ser conferidos nos eventos e atos posteriores.'],
['Por que a receita aparece como estimada?','Subtraímos dos lances vencedores os valores vinculados a não pagamento identificado. Por premissa, os demais ficam no grupo com pagamento estimado. A ausência de registro de não pagamento não é comprovante de pagamento; por isso não chamamos o saldo de receita líquida efetiva.'],
['O que acontece depois do leilão?','O interessado deve cumprir o procedimento de requerimento e as condições do regime. A trajetória pode continuar em novo processo associado. Acompanhamos as ligações, títulos, guias, comercialização declarada e CFEM, respeitando os ciclos e suas datas.'],
['Quando surge a CFEM?','O arremate de uma área não gera CFEM por si só. A obrigação decorre das hipóteses previstas em lei, como venda ou consumo de bem mineral. Na extração sob PLG, o primeiro adquirente recolhe na hipótese legal. Título ou guia indicam potencial de atividade, não prova automática de dívida.'],
['A 6ª rodada e a 7ª entram na receita comercial?','Não. A 6ª segue avaliação social para PLG: acompanhamos requerimentos, associados e CFEM posterior separadamente. A 7ª teve o edital cancelado. Não se deve representar esses casos como fracasso de arrecadação com lance zero.'],
['O estoque apresentado é atualizado em tempo real?','Não. É o retrato da extração exibida. Aptidão não significa inclusão automática na próxima rodada. As decisões de oferta dependem da avaliação administrativa e das condições aplicáveis.']
].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}<p class="blueSourceNote">Fontes: <a href="https://www.gov.br/anm/pt-br/assuntos/disponibilidade-de-areas" target="_blank" rel="noopener">disponibilidade na ANM</a>, <a href="https://www.gov.br/anm/pt-br/acesso-a-informacao/perguntas-frequentes/disponibilidade-de-areas" target="_blank" rel="noopener">perguntas frequentes oficiais</a> e <a href="https://www.planalto.gov.br/ccivil_03/leis/l8001compilado.htm" target="_blank" rel="noopener">Lei 8.001</a>. Para decidir um caso, consulte a versão vigente e o edital do respectivo período.</p></div>`}

function unifiedPanorama(){const hero=document.querySelector('#editorialOpening .observatoryHero');if(!hero)return;const s=D.areaScenario.summary,stock=D.stockSummary,offered=D.auctionContext.rounds.filter(r=>![6,7].includes(r.round)).reduce((n,r)=>n+r.included,0),compact=c=>'R$ '+(c/1e8).toLocaleString('pt-BR',{maximumFractionDigits:2})+' mi';hero.querySelector('.eyebrow').textContent='OBSERVATÓRIO DOS LEILÕES MINERAIS · DADOS ABERTOS';hero.querySelector('h2').innerHTML='O arremate é o começo.<br><span>O que acontece depois?</span>';hero.querySelector('p').textContent='Do lance aos royalties. Veja quais áreas avançaram, o que merece atenção e o que ainda precisamos esclarecer.';const items=[['01','Áreas ofertadas*',num(offered),'Nas 6 rodadas comerciais','rounds'],['02','Áreas arrematadas',num(s.awarded),pct(s.awarded,offered)+' das ofertadas · 7.526 origens','rounds'],['03','Lances vencedores',compact(s.bid_cents),'Valor total das propostas vencedoras','rounds'],['04','Não pagamento identificado',compact(s.unpaid_cents),num(s.unpaid)+' áreas · '+pct(s.unpaid,s.awarded)+' dos arremates','rounds'],['05','Saldo',compact(s.bid_cents-s.unpaid_cents),'Após descontar o não pagamento identificado','rounds'],['06','Áreas com pagamento estimado',num(s.estimated_paid),pct(s.estimated_paid,s.awarded)+' dos arremates','rounds'],['07','Áreas com CFEM posterior',num(s.cfem_areas),pct(s.cfem_areas,s.estimated_paid)+' das áreas com pagamento estimado','processes'],['08','CFEM nominal posterior',compact(s.cfem_cents),'Recolhida nas '+num(s.cfem_areas)+' áreas · até jun./2026','cfem']];hero.querySelector('.blueHeroMetrics').innerHTML=items.map(([step,label,value,note,route])=>`<button class="journeyMetric" data-journey="${route}" title="${esc(label)}: ${esc(note)}. Abrir detalhamento"><strong>${value}</strong><span class="journeyStep">${label}</span><small>${note}</small></button>`).join('');hero.querySelector('.blueHeroNote').innerHTML=`8 rodadas acompanhadas · 2020–2024 · 6 comerciais, 6ª social e 7ª cancelada. <button class="heroMethodLink" id="heroNumbersHelp">Como ler esses números?</button>`;hero.querySelectorAll('[data-journey]').forEach(b=>b.onclick=()=>{if(b.dataset.journey==='processes'){$('reset').click();window.managementMode='results';render()}navigate(b.dataset.journey)});$('heroNumbersHelp').onclick=()=>{$('panoramaNumbersMethod').open=true;$('panoramaNumbersMethod').scrollIntoView({behavior:'smooth'})};const actions=hero.querySelector('.openingActions');hero.querySelector('.blueHeroMetrics').before(actions);$('blueStart').textContent='Explorar os resultados →';$('blueExplore').textContent='Encontrar uma área';let strip=document.createElement('div');strip.className='heroStock';strip.innerHTML=`<div><span>PRÓXIMAS RODADAS</span><strong>${num(stock.eligible_unique)} aptas à disponibilidade</strong><p>Registros de áreas que podem ser avaliados para uma nova oferta. Aptidão não significa inclusão automática em um edital.</p></div><div><small>Estoque consultado em ${date(stock.extraction)}</small><button id="heroStockDetail">Entender o estoque ↓</button></div>`;hero.append(strip);$('heroStockDetail').onclick=()=>$('stockExplanation').scrollIntoView({behavior:'smooth'});const summary=$('executiveSummary');if(summary){summary.querySelector('.executiveMetrics')?.remove();summary.querySelector('.blueKicker').textContent='Entenda os próximos passos';summary.querySelector('h2').textContent='O que esses resultados ajudam a acompanhar?';const notice=summary.querySelector('.blueNotice');if(notice){const d=document.createElement('details');d.id='panoramaNumbersMethod';d.className='blueSection';d.innerHTML='<summary>Como ler a oferta, o saldo dos lances e a CFEM?</summary><p>* Oferta: registros das rodadas comerciais na base, incluindo áreas posteriormente retiradas ou suspensas. A mesma área pode aparecer em outra rodada. O percentual de arremates usa esse conjunto de registros.</p>';notice.before(d);d.append(notice);d.insertAdjacentHTML('beforeend','<p>CFEM nominal: soma dos valores registrados, sem correção monetária. O valor de CFEM não é o valor dos lances, e a relação temporal não comprova efeito causado pelo leilão. Os números da capa são gerais, independentemente dos filtros de exploração.</p>')}const stockArticle=summary.querySelector('.blueGrid article');if(stockArticle)stockArticle.id='stockExplanation'}
}

const absenceLabels={productive:'Lavra, licenciamento ou PLG no cadastro',guide:'Pesquisa com guia no prazo e substância identificada',review:'Guia, título ou prazo precisam de conferência',early:'Sem fase produtiva ou guia autorizada localizada',missing:'Fase ou associado não localizado'};
function absenceAssessment(r){const out=[];for(const p of r.sucessores_candidatos){const phase=E.phases[p]?.fase||'',f=fold(phase),gs=guideRecords(p),g=gs.filter(x=>x.authorization).sort((a,b)=>a.date.localeCompare(b.date)).at(-1),prod=['concessao de lavra','licenciamento','lavra garimpeira','permissao de lavra garimpeira'].includes(f),titles=(E.titles[p]||[]).filter(t=>t.publicacao<='2026-06-30'&&/concess|licenc|lavra garimpeira/i.test(fold(t.documento))),assessment=g?guideAssessment(p,'2026-06'):'',substances=[...new Set((g?.limits||[]).map(l=>l.substance))],start=prod?titles.map(t=>t.publicacao).sort()[0]:g?.date;let key=!phase?'missing':prod?'productive':g?(f==='autorizacao de pesquisa'&&assessment==='Dentro do prazo estimado da guia'&&substances.length?'guide':'review'):'early';out.push({p,phase,key,start,months:start?Math.max(0,(2026-Number(start.slice(0,4)))*12+6-Number(start.slice(5,7))):null,substances,assessment,g,reason:prod?'Fase na extração; conferir título e vigência até junho/2026':g?assessment:'Não foi localizada autorização de guia neste levantamento'})}const key=['productive','guide','review','early','missing'].find(k=>out.some(x=>x.key===k))||'missing';return {r,key,items:out}}
function absencePanel(){const matrix=$('cfemComparisonMatrix');if(!matrix)return;const rows=(window.cfemComparisonBase||[]).filter(r=>!businessStopped(r)&&r.antes&&r.depois&&r.transicao==='sem_positivo_antes_e_depois'),cases=rows.map(absenceAssessment);let box=$('absenceDiagnostic');if(!box){box=document.createElement('section');box.id='absenceDiagnostic';box.className='blueSection';matrix.after(box);routeNodes.set(box,'results')}box.classList.toggle('routeHidden',activeRoute!=='results');box.innerHTML=`<span class="blueKicker">Entenda a ausência de recolhimentos</span><h2>${num(cases.length)} áreas acompanhadas sem CFEM antes nem depois</h2><p>A contagem usa o processo de origem como identificador da área e conta cada origem uma vez. Ausência de CFEM não explica, sozinha, o motivo. O próximo passo é conferir o novo processo, o título e a guia.</p><div class="blueGrid">${Object.entries(absenceLabels).map(([k,t])=>`<article><button data-absence="${k}" aria-pressed="${window.absenceGroup===k}"><strong class="big">${num(cases.filter(c=>c.key===k).length)}</strong>${t}</button></article>`).join('')}</div><p class="blueNotice">“Potencial” significa que há um sinal de possibilidade de atividade. Não prova produção ou dívida de CFEM. A fase é a da extração de setembro/2026; o recolhimento termina em junho/2026. Guia no prazo usa a publicação e o prazo extraído, sem certificar todas as condições de vigência. Na PLG, verifique também o primeiro adquirente.</p><button id="absenceAll">Ver todos os grupos</button><div id="absenceRows" class="blueTableWrap"></div><p class="note">Grupos exclusivos por área: prevalece fase produtiva, depois guia no prazo, conferência, fase anterior e falta de informação. Um caso com vários associados aparece uma vez na contagem e pode ter várias linhas no detalhe. Esta seleção filtra a tabela abaixo; os filtros gerais continuam valendo.</p>`;const draw=()=>{const selected=cases.filter(c=>!window.absenceGroup||c.key===window.absenceGroup);$('absenceRows').innerHTML=`<p>${num(selected.length)} áreas neste grupo. Exibindo as primeiras 100; refine pelos filtros gerais.</p><table><thead><tr><th>Área / origem → novo processo</th><th>Fase do associado</th><th>Substância da guia</th><th>Início / tempo até jun.2026</th><th>O que conferir</th></tr></thead><tbody>${selected.slice(0,100).flatMap(c=>(c.items.length?c.items:[{p:'Não localizado',phase:'Não localizada',reason:'Associação a conferir',substances:[]}]).map(v=>`<tr><td><button data-absence-case="${c.r.origem}">${c.r.origem} → ${v.p}</button></td><td>${esc(v.phase)}</td><td>${esc(v.substances.join(', ')||'Não extraída na guia')}</td><td>${v.start?date(v.start)+' · '+v.months+' meses':'Data a conferir'}</td><td>${esc(v.reason)}</td></tr>`)).join('')}</tbody></table>`;box.querySelectorAll('[data-absence-case]').forEach(b=>b.onclick=()=>{$('search').value=b.dataset.absenceCase;window.managementMode='all';$('transition').value='';render();navigate('processes')});box.querySelectorAll('[data-absence]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.absence===window.absenceGroup)))};box.querySelectorAll('[data-absence]').forEach(b=>b.onclick=()=>{window.absenceGroup=b.dataset.absence;draw()});$('absenceAll').onclick=()=>{window.absenceGroup='';draw()};draw();matrix.querySelectorAll('small,.note,#matrixSelection span').forEach(el=>{el.innerHTML=el.innerHTML.replaceAll('origens comparáveis','áreas acompanhadas comparáveis').replaceAll('por origem observada','por área acompanhada')});window.absenceAudit=Object.fromEntries(Object.keys(absenceLabels).map(k=>[k,cases.filter(c=>c.key===k).length]));}


function guideAuditPanel(){let box=$('quantityGuideOverview');if(!box){box=document.createElement('section');box.id='quantityGuideOverview';box.className='blueSection';$('absenceDiagnostic').after(box);routeNodes.set(box,'results')}box.classList.toggle('routeHidden',activeRoute!=='results');const ps=new Map();for(const r of filtered)for(const p of r.sucessores_candidatos)if(!ps.has(p))ps.set(p,r);const checks=[...ps].flatMap(([p,r])=>guideQuantityChecks(p).map(c=>({p,r,c}))),flagged=checks.filter(({c})=>c.ratio>100||/após|diferentes|Alteração|conferir/.test(c.status));box.innerHTML=`<h2>Guia de utilização: prazo, substância e quantidade</h2><p>${num(ps.size)} processos associados no recorte · ${num(new Set(checks.map(v=>v.p)).size)} com limite extraído para comparação · ${num(flagged.length)} comparações com pontos para conferir.</p><p>Comparamos a substância e a unidade da comercialização declarada com o limite extraído da guia. Limites anuais são acompanhados por aniversário da publicação; meses de transição precisam de conferência diária. Quantidade comercializada não é produção física medida.</p><details><summary>Abrir alertas e percentuais dos limites</summary><div class="blueTableWrap"><table><thead><tr><th>Origem → associado</th><th>Guia / substância / ciclo</th><th>Comercialização comparada</th><th>Limite / utilização</th><th>Alertas simultâneos</th></tr></thead><tbody>${checks.slice(0,300).map(({p,r,c})=>{const alerts=[];if(c.ratio>100)alerts.push('Acima do limite: '+c.ratio.toFixed(1)+'%');if(c.status!=='Sem divergência nesta comparação')alerts.push(c.status);if(c.g.explicitEnd||c.g.estimatedEnd){const end=(c.g.explicitEnd||c.g.estimatedEnd).slice(0,7);if(c.months.some(m=>m>end))alerts.push('Há registros após o prazo; total pode incluir período fora da guia')}return `<tr><td><button data-quantity-origin="${r.origem}">${r.origem} → ${p}</button></td><td>${esc(c.g.number||c.g.code)} · ${esc(c.l.substance)} · ${c.key}</td><td>${c.qty.toLocaleString('pt-BR',{maximumFractionDigits:3})} ${esc(c.l.unit)}</td><td>${c.l.quantity.toLocaleString('pt-BR')} ${esc(c.l.unit)} · ${c.ratio.toFixed(1)}%</td><td>${esc(alerts.join(' · ')||'Sem divergência detectada nesta comparação; não certifica regularidade')}</td></tr>`}).join('')||'<tr><td colspan="5">Limites comparáveis não localizados no recorte.</td></tr>'}</tbody></table></div><p>Primeiras 300 comparações; refine os filtros ou abra o processo para ver o histórico completo.</p></details><p class="note">Falta de limite extraído não significa quantidade ilimitada nem conformidade. Unidades incompatíveis não são somadas; areia e minério de manganês em kg são convertidos para t. Mesmo acima do limite, o achado exige verificar competência, estoque, retificação e condições do ato antes de concluir irregularidade.</p>`;box.querySelectorAll('[data-quantity-origin]').forEach(b=>b.onclick=()=>{$('search').value=b.dataset.quantityOrigin;$('transition').value='';window.managementMode='all';render();navigate('processes')});window.guideAuditCounts={associated:ps.size,comparable:new Set(checks.map(v=>v.p)).size,checks:checks.length,flagged:flagged.length,above:checks.filter(v=>v.c.ratio>100).length};}

