/* Accessible sorting of rendered table rows; pagination scope is explicit. */
function tableCellValue(cell){const text=(cell?.dataset?.sortValue??cell?.innerText??'').trim();if(!text||/^(—|–|-|não se aplica|não localizado|não informad|a conferir|cancelad)/i.test(text))return {kind:'missing',v:''};if(/^\d{3}\.\d{3}\/\d{4}/.test(text))return {kind:'text',v:text};const dt=text.match(/^(\d{2})\/(\d{2})\/(\d{4})/);if(dt)return {kind:'number',v:Number(dt[3]+dt[2]+dt[1])};const mm=text.match(/^(\d{2})\/(\d{4})$/);if(mm)return {kind:'number',v:Number(mm[2]+mm[1])};const iso=text.match(/^(\d{4})-(\d{2})(?:-(\d{2}))?$/);if(iso)return {kind:'number',v:Number(iso[1]+iso[2]+(iso[3]||'01'))};const n=text.replace(/^R\$\s*/,'').match(/^[-+]?\d[\d.]*(?:,\d+)?/);if(n)return {kind:'number',v:Number(n[0].replaceAll('.','').replace(',','.'))};return {kind:'text',v:text};}
function installTableSorting(){const collator=new Intl.Collator('pt-BR',{numeric:true,sensitivity:'base'});function enhance(){document.querySelectorAll('table').forEach(table=>{const row=table.tHead?.rows[table.tHead.rows.length-1];if(!row||table.dataset.orderReady)return;table.dataset.orderReady='true';const note=document.createElement('p');note.className='tableSortNote';note.textContent='Ordenar: clique no título da coluna. ↑ crescente · ↓ decrescente. Em tabelas paginadas ou limitadas, ordena as linhas exibidas; campos compostos usam o primeiro valor. Linhas especiais ficam ao final.';table.before(note);[...row.cells].forEach((th,index)=>{if(th.colSpan!==1||th.querySelector('button,input,select'))return;const label=th.textContent.trim();if(!label)return;th.setAttribute('scope','col');th.setAttribute('aria-sort','none');const button=document.createElement('button');button.type='button';button.className='tableOrderButton';button.textContent=label+' ↕';button.setAttribute('aria-label','Ordenar por '+label);th.replaceChildren(button);button.onclick=()=>{const direction=th.getAttribute('aria-sort')==='ascending'?-1:1;[...row.cells].forEach(h=>{h.setAttribute('aria-sort','none');const b=h.querySelector('.tableOrderButton');if(b)b.textContent=b.dataset.label+' ↕'});button.dataset.label=label;th.setAttribute('aria-sort',direction===1?'ascending':'descending');button.textContent=label+(direction===1?' ↑':' ↓');for(const body of table.tBodies){const rows=[...body.rows],normal=rows.filter(r=>r.cells.length===row.cells.length&&[...r.cells].every(c=>c.colSpan===1)),special=rows.filter(r=>!normal.includes(r));normal.sort((a,b)=>{const av=tableCellValue(a.cells[index]),bv=tableCellValue(b.cells[index]);if(av.kind==='missing'||bv.kind==='missing')return av.kind===bv.kind?0:av.kind==='missing'?1:-1;return direction*(av.kind==='number'&&bv.kind==='number'?av.v-bv.v:collator.compare(String(av.v),String(bv.v)))});body.append(...normal,...special)}note.textContent='Ordenação: '+label+' · '+(direction===1?'crescente':'decrescente')+'. Aplicada às linhas exibidas; primeiro valor em campos compostos. Linhas especiais e valores ausentes ao final.'};button.dataset.label=label})})}let scheduled=false;new MutationObserver(records=>{if(!records.some(r=>r.addedNodes.length))return;if(!scheduled){scheduled=true;requestAnimationFrame(()=>{scheduled=false;enhance()})}}).observe(document.body,{childList:true,subtree:true});enhance();}
installTableSorting();

function postAuctionData(r){const cut='2026-06',rd=$('round').value,inside=(p,m)=>!!r.depois&&(r.cycleWindows?r.cycleWindows.some(w=>w.process===p&&w.startExcluded<m&&m<w.endExcluded&&(!rd||w.round==rd)):m>r.data_referencia.slice(0,7)&&m<=cut),commercial=[],seen=new Set();for(const p of r.sucessores_candidatos)for(const x of E.production[p]||[]){if(inside(p,x[0])&&!seen.has(x)){seen.add(x);commercial.push({p,x})}}const pay=payments(r).filter(v=>v.x[6]>0),firstQ=commercial.filter(v=>v.x[5]>0).map(v=>v.x[0]).sort()[0],firstP=pay.map(v=>v.x[0]).sort()[0],groups=new Map();for(const {p,x} of commercial){const k=JSON.stringify([x[1],x[2]]);if(!groups.has(k))groups.set(k,{sub:x[1],unit:x[2],quantity:0,months:new Map(),processes:new Set()});const g=groups.get(k);g.quantity+=x[5];g.months.set(x[0],(g.months.get(x[0])||0)+x[5]);g.processes.add(p)}const cfemMonths=new Map();for(const {x} of pay)cfemMonths.set(x[0],(cfemMonths.get(x[0])||0)+x[6]);const events=r.sucessores_candidatos.flatMap(p=>(E.successorEvents[p]||[]).filter(e=>e[0]<='2026-06-30'&&e[0]>=(r.homologacao_original||r.data_referencia)&&/alvara|concessao|licenciamento|lavra garimpeira|guia utiliz|requerimento pesquisa|relatorio pesquisa.*aprov|renuncia|caducidade|arquivamento/i.test(fold(E.eventNames[e[1]]||''))).map(e=>({p,date:e[0],code:e[1],name:E.eventNames[e[1]]||e[1]}))).sort((a,b)=>a.date.localeCompare(b.date));return {commercial,firstQ,firstP,groups:[...groups.values()],pay,cfemMonths,events}}
function elapsedMonthLabel(start,end){if(!start||!end)return 'Não calculável';const n=(+end.slice(0,4)-(+start.slice(0,4)))*12+(+end.slice(5,7)-(+start.slice(5,7)));return n>=0?n+' meses-calendário':'Registro anterior ao marco; conferir'}
function postAuctionStory(r){const d=postAuctionData(r),hom=r.homologacao_original||r.data_referencia,association=r.vinculos.map(v=>v.associacao).filter(Boolean).sort()[0],months=r.depois?.meses_observados,total=r.depois?.reais;return `<section id="postAuctionStory" class="blueSection"><span class="blueKicker">Depois do leilão · a trajetória desta área</span><h2>Avançou? Comercializou? Recolheu CFEM?</h2><p>Área identificada pelo processo ${esc(r.origem)}. A história continua nos números associados abaixo.</p><div class="blueSimpleFlow"><div><b>Arremate / homologação</b>${date(hom)}</div><div><b>Associação localizada</b>${association?date(association):'Não localizada'}</div><div><b>Primeira comercialização declarada</b>${d.firstQ?month(d.firstQ):r.depois?'Não encontrada na janela':'Comparação não disponível'}</div><div><b>Primeira CFEM encontrada</b>${d.firstP?month(d.firstP):r.depois?'Não encontrada na janela':'Comparação não disponível'}</div></div><div class="blueGrid"><article><h3>CFEM nominal posterior</h3><strong class="big">${total==null?'Não avaliável':money(total)}</strong><p>${months?money(total/months)+' por mês observado · '+num(months)+' meses no denominador':'Denominador mensal não disponível'}</p></article><article><h3>Regularidade observada</h3><strong class="big">${num(d.cfemMonths.size)} meses</strong><p>Com CFEM positiva localizada${months?' · '+pct(d.cfemMonths.size,months)+' dos meses observados':''}. Não equivale à regularidade fiscal.</p></article><article><h3>Tempo desde a homologação</h3><p>Até comercialização: <b>${elapsedMonthLabel(hom,d.firstQ)}</b><br>Até CFEM: <b>${elapsedMonthLabel(hom,d.firstP)}</b><br>Associação → CFEM: <b>${elapsedMonthLabel(association,d.firstP)}</b></p></article></div><h3>Quanto foi comercializado, por substância?</h3><div class="blueTableWrap"><table><thead><tr><th>Substância declarada</th><th>Quantidade acumulada</th><th>Unidade</th><th>Meses com quantidade positiva</th><th>Processos associados</th></tr></thead><tbody>${d.groups.map(g=>`<tr><td>${esc(g.sub)}</td><td>${g.quantity.toLocaleString('pt-BR',{maximumFractionDigits:3})}</td><td>${esc(g.unit)}</td><td>${[...g.months.values()].filter(v=>v>0).length}</td><td>${[...g.processes].join(' · ')}</td></tr>`).join('')||'<tr><td colspan="5">Comercialização declarada não localizada nesta janela. Isso não comprova ausência de produção.</td></tr>'}</tbody></table></div><details><summary>Ver a evolução mensal da comercialização e da CFEM</summary><div class="blueTableWrap"><table><thead><tr><th>Mês</th><th>Substância</th><th>Quantidade no mês</th><th>Unidade</th><th>Acumulado da substância / unidade</th></tr></thead><tbody>${d.groups.flatMap(g=>{let cumulative=0;return [...g.months].sort().map(([m,q])=>{cumulative+=q;return `<tr><td>${month(m)}</td><td>${esc(g.sub)}</td><td>${q.toLocaleString('pt-BR',{maximumFractionDigits:3})}</td><td>${esc(g.unit)}</td><td>${cumulative.toLocaleString('pt-BR',{maximumFractionDigits:3})}</td></tr>`})}).join('')}</tbody></table><table><thead><tr><th>Mês com CFEM</th><th>CFEM positiva registrada</th></tr></thead><tbody>${[...d.cfemMonths].sort().map(([m,c])=>`<tr><td>${month(m)}</td><td>${money(c/100)}</td></tr>`).join('')}</tbody></table></div></details><h3>Como o processo avançou?</h3><p>${r.sucessores_candidatos.map(p=>`<b>${p}</b>: ${esc(E.phases[p]?.fase||'fase não localizada')}`).join('<br>')}</p><p class="note">Acima: fase atual na extração de setembro/2026. Abaixo: atos publicados encontrados até junho/2026. Um requerimento não é outorga; os eventos não constituem uma reconstrução completa de todas as fases históricas.</p><div class="blueTableWrap"><table><thead><tr><th>Data do evento</th><th>Processo</th><th>Ato ou evento documentado</th><th>Código</th></tr></thead><tbody>${d.events.map(e=>`<tr><td>${date(e.date)}</td><td>${e.p}</td><td>${esc(e.name)}</td><td>${e.code}</td></tr>`).join('')||'<tr><td colspan="4">Atos de avanço não localizados no período pesquisado.</td></tr>'}</tbody></table></div><p class="blueNotice">Quantidade comercializada provém dos registros de CFEM; não é comprovação independente de produção. CFEM nominal não foi corrigida pela inflação. As janelas por ciclo, meses de transição e o marco escolhido nos filtros são preservados. “Primeiro” significa primeiro registro encontrado nessa janela, não necessariamente o início real da atividade. Valores mensais positivos não incluem eventuais ajustes negativos; o total e a média usam a métrica financeira da comparação.</p></section>`}
function postAuctionOverview(){let box=$('postAuctionOverview');if(!box){box=document.createElement('section');box.id='postAuctionOverview';box.className='blueSection';$('executiveSummary').after(box);routeNodes.set(box,'results')}box.classList.toggle('routeHidden',activeRoute!=='results');const rr=filtered.filter(r=>!businessStopped(r)&&r.depois),data=rr.map(r=>({r,d:postAuctionData(r)})),commercial=data.filter(v=>v.d.firstQ),paid=data.filter(v=>v.d.firstP),acts=data.filter(v=>v.d.events.length);box.innerHTML=`<span class="blueKicker">Resultados do recorte · três perguntas</span><h2>O que já aconteceu depois do leilão?</h2><div class="blueGrid"><article><strong class="big">${num(acts.length)}</strong><h3>Com atos de tramitação encontrados</h3><p>Requerimentos, outorgas, guias e desfechos no período. Abra o processo para distinguir avanço de interrupção.</p></article><article><strong class="big">${num(commercial.length)}</strong><h3>Com comercialização declarada</h3><p>Quantidade positiva encontrada. Cada substância e unidade tem seu próprio acumulado.</p></article><article><strong class="big">${num(paid.length)}</strong><h3>Com CFEM positiva encontrada</h3><p>Confira total nominal, primeiro mês e regularidade no detalhe.</p></article></div><p>Contagens por área acompanhada, identificada pelo processo de origem, entre ${num(rr.length)} trajetórias avaliáveis do recorte. Grupos podem se sobrepor; não representam etapas obrigatoriamente consecutivas.</p><button id="openPostAuctionCases" class="bluePrimary">Abrir a história de uma área →</button>`;$('openPostAuctionCases').onclick=()=>navigate('processes')}
